import numpy as np, torch, model
net=model.load(); neg=model.negatives(); uid=list(neg['uid'])
def unit(d): r=np.radians(d); return np.array([np.cos(r),np.sin(r)],dtype=np.float32)
def dec(xs,cs):
    r=model.decode(net,xs,cs)
    if isinstance(r,(tuple,list)): r=r[0]
    return np.asarray(r,dtype=np.float32).reshape(-1,2)
st={'k':0,'cfg':None,'x':None}
def h_inp(m,i,o): st['x']=i[0]
def h_out(m,i,o):
    k=st['k']; st['k']+=1; cfg=st['cfg']
    if cfg is None or k>=1: return o
    x=st['x']; fire=((x@cfg[0])>0).float().unsqueeze(-1)
    return o+fire*(torch.relu(x@cfg[1]+0.2).unsqueeze(-1)*cfg[2])
net.inp.register_forward_hook(h_inp); net.out.register_forward_hook(h_out)
def run(xs,cs,cfg):
    st.update(k=0,cfg=cfg)
    with torch.no_grad(): return dec(xs,cs)
